    private Item montarItem(ResumoRequest.ItemRequest i) {
        if (i == null
                || i.precoUnitario() == null || i.precoUnitario().signum() <= 0
                || i.quantidade() == null || i.quantidade() <= 0
                || i.pesoKg() == null || i.pesoKg().signum() <= 0) {
